CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized kernel for fixed 2x2x2 pooling with even spatial dimensions.
// Assumes D_in, H_in, W_in are all even (no boundary checks needed).
__global__ void fused_divide_max_pool_2x2x2_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float inv_divisor,
    const int N, const int C,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * D_out * H_out * W_out;

    if (idx >= total) return;

    // Decompose flat index
    const int w_out = idx % W_out;
    const int h_out = (idx / W_out) % H_out;
    const int d_out = (idx / (W_out * H_out)) % D_out;
    const int c     = (idx / (W_out * H_out * D_out)) % C;
    const int n     = idx / (C * D_out * H_out * W_out);

    // Base pointer for this (n, c) plane
    const int nc_offset = (n * C + c) * D_in * H_in * W_in;

    const int d0 = d_out * 2;
    const int h0 = h_out * 2;
    const int w0 = w_out * 2;

    // Load all 8 values of the 2x2x2 window, no bounds checks (even dims)
    const int HW = H_in * W_in;
    const int base00 = nc_offset + d0 * HW + h0 * W_in + w0;
    const int base01 = base00 + 1;
    const int base10 = base00 + W_in;
    const int base11 = base10 + 1;
    const int base_d1 = HW;

    float v0 = __ldg(&input[base00]);
    float v1 = __ldg(&input[base01]);
    float v2 = __ldg(&input[base10]);
    float v3 = __ldg(&input[base11]);
    float v4 = __ldg(&input[base00 + base_d1]);
    float v5 = __ldg(&input[base01 + base_d1]);
    float v6 = __ldg(&input[base10 + base_d1]);
    float v7 = __ldg(&input[base11 + base_d1]);

    float max_val = fmaxf(fmaxf(fmaxf(v0, v1), fmaxf(v2, v3)),
                          fmaxf(fmaxf(v4, v5), fmaxf(v6, v7)));

    output[idx] = max_val * inv_divisor;
}

// Generic kernel for arbitrary pool sizes (fallback path)
__global__ void fused_divide_max_pool_generic_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float inv_divisor,
    const int N, const int C,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out,
    const int pool_d, const int pool_h, const int pool_w
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * D_out * H_out * W_out;

    if (idx >= total) return;

    const int w_out = idx % W_out;
    const int h_out = (idx / W_out) % H_out;
    const int d_out = (idx / (W_out * H_out)) % D_out;
    const int c     = (idx / (W_out * H_out * D_out)) % C;
    const int n     = idx / (C * D_out * H_out * W_out);

    const int d_start = d_out * pool_d;
    const int h_start = h_out * pool_h;
    const int w_start = w_out * pool_w;

    float max_val = -1e38f;

    for (int pd = 0; pd < pool_d; ++pd) {
        const int d_idx = d_start + pd;
        if (d_idx >= D_in) continue;
        for (int ph = 0; ph < pool_h; ++ph) {
            const int h_idx = h_start + ph;
            if (h_idx >= H_in) continue;
            for (int pw = 0; pw < pool_w; ++pw) {
                const int w_idx = w_start + pw;
                if (w_idx >= W_in) continue;
                const int in_idx = ((n * C + c) * D_in + d_idx) * H_in * W_in + h_idx * W_in + w_idx;
                const float val = __ldg(&input[in_idx]) * inv_divisor;
                max_val = fmaxf(max_val, val);
            }
        }
    }

    output[idx] = max_val;
}

torch::Tensor fused_divide_max_pool(torch::Tensor input, float divisor, int pool_d, int pool_h, int pool_w) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(divisor != 0.0f, "divisor must be non-zero");

    const int N = input.size(0);
    const int C = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int D_out = (D_in + pool_d - 1) / pool_d;
    const int H_out = (H_in + pool_h - 1) / pool_h;
    const int W_out = (W_in + pool_w - 1) / pool_w;

    auto output = torch::empty({N, C, D_out, H_out, W_out}, input.options());

    const int total = N * C * D_out * H_out * W_out;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    const float inv_divisor = 1.0f / divisor;

    // Dispatch specialized 2x2x2 path when dims are even (no boundary checks needed)
    if (pool_d == 2 && pool_h == 2 && pool_w == 2 &&
        (D_in % 2 == 0) && (H_in % 2 == 0) && (W_in % 2 == 0)) {
        fused_divide_max_pool_2x2x2_kernel<<<blocks, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            inv_divisor,
            N, C, D_in, H_in, W_in,
            D_out, H_out, W_out
        );
    } else {
        fused_divide_max_pool_generic_kernel<<<blocks, threads>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            inv_divisor,
            N, C, D_in, H_in, W_in,
            D_out, H_out, W_out,
            pool_d, pool_h, pool_w
        );
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D convolution, divides by a constant, applies max pooling,
        global average pooling, adds a bias term, and sums along a specific dimension.
        """
    def __init__(self, in_channels, out_channels, kernel_size, divisor, pool_size, bias_shape, sum_dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
