#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// ---------------------------------------------------------------------------
// Specialized 2x2x2 fused divide + max-pool kernel
// Precomputes strides to minimize per-thread register usage
// ---------------------------------------------------------------------------
__global__ void fused_divide_max_pool_kernel_2x2x2(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float inv_divisor,
    const int N, const int C,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * D_out * H_out * W_out;
    if (idx >= total) return;

    // Decode output index
    const int HW_out = H_out * W_out;
    const int DHW_out = D_out * HW_out;
    const int w_out = idx % W_out;
    const int h_out = (idx / W_out) % H_out;
    const int d_out = (idx / HW_out) % D_out;
    const int c     = (idx / DHW_out) % C;
    const int n     = idx / (C * DHW_out);

    // Precompute base offsets to reduce live registers
    const int HW_in    = H_in * W_in;
    const int plane_in = D_in * HW_in;
    const int base_nc  = (n * C + c) * plane_in;

    const int d0 = d_out * 2;
    const int d1 = d0 + 1;
    const int h0 = h_out * 2;
    const int h1 = h0 + 1;
    const int w0 = w_out * 2;
    const int w1 = w0 + 1;

    const bool d1_ok = (d1 < D_in);
    const bool h1_ok = (h1 < H_in);
    const bool w1_ok = (w1 < W_in);

    // base_d0 / base_d1 are row-plane bases
    const int base_d0 = base_nc + d0 * HW_in;
    const int base_d1 = base_nc + d1 * HW_in;  // only used if d1_ok

    float mv = -INFINITY;

    // d=d0, h=h0
    {
        const int bh = base_d0 + h0 * W_in;
        mv = fmaxf(mv, __ldg(&input[bh + w0]) * inv_divisor);
        if (w1_ok) mv = fmaxf(mv, __ldg(&input[bh + w1]) * inv_divisor);
    }
    // d=d0, h=h1
    if (h1_ok) {
        const int bh = base_d0 + h1 * W_in;
        mv = fmaxf(mv, __ldg(&input[bh + w0]) * inv_divisor);
        if (w1_ok) mv = fmaxf(mv, __ldg(&input[bh + w1]) * inv_divisor);
    }
    // d=d1, h=h0
    if (d1_ok) {
        const int bh = base_d1 + h0 * W_in;
        mv = fmaxf(mv, __ldg(&input[bh + w0]) * inv_divisor);
        if (w1_ok) mv = fmaxf(mv, __ldg(&input[bh + w1]) * inv_divisor);
        // d=d1, h=h1
        if (h1_ok) {
            const int bh2 = base_d1 + h1 * W_in;
            mv = fmaxf(mv, __ldg(&input[bh2 + w0]) * inv_divisor);
            if (w1_ok) mv = fmaxf(mv, __ldg(&input[bh2 + w1]) * inv_divisor);
